"""Generate the point-group reference fixture `tables.txt` from PySCF.

Run with the pyscf env:
    ~/miniforge3/envs/pyscf/bin/python generate.py

For each abelian point group a FCIDUMP can carry (C1, Ci, C2, Cs, D2, C2v, C2h,
D2h), emits:
  - the irrep names in Molpro ORBSYM order (ids 1..|G|),
  - the Molpro-id -> XOR-index permutation (PySCF's internal irrep ids for these
    groups ARE the XOR-compatible indices; ORBSYM_MAP gives PySCF id -> Molpro id),
  - the full |G| x |G| direct-product table in Molpro numbering, computed by
    pyscf.symm.direct_prod on PySCF ids and converted.

The script verifies, before writing anything, that for every group the PySCF
direct product is exactly XOR on the PySCF ids — i.e. the emitted permutation
really does make `(molpro->xor(i)) ^ (molpro->xor(j))` the correct product.
The Rust tables in src/pointgroup.rs are pinned against this file by a unit
test; regenerate only with PySCF, never edit by hand.
"""
import numpy as np
from pyscf import symm
from pyscf.symm import param
from pyscf.tools.fcidump import ORBSYM_MAP

GROUPS = ["C1", "Ci", "C2", "Cs", "D2", "C2v", "C2h", "D2h"]

lines = ["# Point-group direct-product reference tables, generated by generate.py"]
lines.append("# (PySCF %s). Molpro ORBSYM ids are 1-based; XOR indices are 0-based." % __import__("pyscf").__version__)

for g in GROUPS:
    pyscf_to_molpro = ORBSYM_MAP[g]  # pyscf id -> molpro id (1-based)
    n = len(pyscf_to_molpro)
    ids = np.arange(n)

    # Verify PySCF ids are XOR-compatible for this group.
    prod = symm.addons.direct_prod(ids, ids, g)
    assert np.array_equal(prod, ids[:, None] ^ ids), f"{g}: direct_prod is not XOR on PySCF ids"

    # Verify the map is a bijection onto 1..n.
    assert sorted(pyscf_to_molpro) == list(range(1, n + 1)), f"{g}: ORBSYM_MAP not a permutation"

    molpro_to_xor = [0] * n  # index: molpro id - 1 -> pyscf/xor id
    for pyscf_id, molpro_id in enumerate(pyscf_to_molpro):
        molpro_to_xor[molpro_id - 1] = pyscf_id

    names = [symm.irrep_id2name(g, i) for i in range(n)]
    names_molpro_order = [names[molpro_to_xor[m]] for m in range(n)]

    lines.append("")
    lines.append(f"group {g} order {n}")
    lines.append("names_molpro_order " + " ".join(names_molpro_order))
    lines.append("molpro_to_xor " + " ".join(str(x) for x in molpro_to_xor))
    lines.append("product_table_molpro")
    # Direct product in Molpro numbering: row i, col j (1-based Molpro ids).
    for i in range(n):
        row = []
        for j in range(n):
            k_xor = molpro_to_xor[i] ^ molpro_to_xor[j]
            row.append(str(pyscf_to_molpro[k_xor]))
        lines.append("  " + " ".join(row))

with open("tables.txt", "w") as f:
    f.write("\n".join(lines) + "\n")
print("wrote tables.txt")
print("\n".join(lines[:20]))
